"use client";

import "@nextlyhq/admin/style.css";
import { RootLayout } from "@nextlyhq/admin";
// Registers every plugin admin component the config declares, as an app's
// admin does: generated by `nextly generate:types` and rewritten by `next dev`
// when it falls behind. It imports the page builder's admin module, so its
// field editor and views register with no hand import.
import "../../../types/plugin-admin-imports.generated";
import "@nextlyhq/plugin-page-builder/styles/editor.css";
// The form builder's views are declared on its collections, which the map does
// not collect, so its admin module still registers them by hand.
import "@nextlyhq/plugin-form-builder/admin";
// Load the style-fixture plugin's admin component + its admin.styles
// (side-effect: registerComponents + CSS import) for the plugin-styling e2e.
import "../../../plugins/style-fixture/admin";

export default function AdminPage() {
  return <RootLayout />;
}
